function validateAppState(value){validateState(value);if(!safePracticeDrafts(value.practiceDrafts))throw Error('Invalid unfinished practice in backup.');if(!safeLearning(value.learning))throw Error('Invalid guided-learning backup.');if(!safeAssessments(value.assessments))throw Error('Invalid grading feedback in backup.');if(value.speakingAnswers!==undefined){if(!value.speakingAnswers||Array.isArray(value.speakingAnswers)||typeof value.speakingAnswers!=='object')throw Error('Invalid speaking answers.');for(const [key,a] of Object.entries(value.speakingAnswers))if(!/^p[123]-\d{1,3}$/.test(key)||!a||!['speaking_points','speaking_transcript'].includes(a.mode)||typeof a.text!=='string'||a.text.length>20000)throw Error('Invalid speaking answer.');}return value;}
