function storageWarning(){if(!storageAvailable&&!$('#storage-warning')){const el=document.createElement('section');el.id='storage-warning';el.className='notice warning';el.setAttribute('role','alert');el.innerHTML='<strong>'+esc(writeBlocked?'Original saved work is protected.':'This session is not saved to this browser.')+'</strong><p>'+esc(writeBlocked?'Automatic saving is paused to avoid overwriting recoverable work. Export your current session and the original recovery copy.':'Browser storage is unavailable or full. Your work remains in this tab; export it before leaving.')+'</p><div class="button-row">'+button('export-data','Export this session','outline small')+(recoveryRaw?button('export-recovery','Export original recovery copy','outline small'):'')+'</div>';$('#main')?.prepend(el);}}
function save(){clearTimeout(saveTimer);if(writeBlocked){storageAvailable=false;$('#save-status').textContent='Saving paused — original work protected';storageWarning();return false;}try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;$('#save-status').textContent='Saved on this browser';$('#storage-warning')?.remove();return true;}catch{storageAvailable=false;$('#save-status').textContent='Not saved — export this session';storageWarning();return false;}}
function queueSave(){clearTimeout(saveTimer);if(!writeBlocked)$('#save-status').textContent='Saving your changes…';saveTimer=setTimeout(save,400);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function link(url,label,cls=''){return `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`;}
function button(action,label,cls='',data=''){return `<button type="button" class="button ${cls}" data-action="${action}" ${data}>${label}</button>`;}
function head(kicker,title,description){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><span class="pill">Academic · target 9 in every skill</span></div>`;}
function empty(title,text,href,label){return `<div class="empty"><strong>${title}</strong>${text}${href?`<br><a class="button small" href="#${href}">${label}</a>`:''}</div>`;}
function prompt(){return prompts.find(p=>p.id===state.selectedPrompt)||prompts[0];}
function draft(){const p=prompt();if(!state.drafts[p.id])state.drafts[p.id]={text:'',checks:checks[p.type].map(()=>false)};return state.drafts[p.id];}
function readTimer(){const t=state.timer;return t?`${t.label} · ${clock(secondsLeft(t))}`:'';}
function timerControls(kind,seconds,label){const mine=state.timer?.kind===kind;return `<div class="timer-box"><div><div class="prompt-meta">${esc(label)}</div><div class="timer-display" data-timer-value="${kind}">${mine?clock(secondsLeft(state.timer)):clock(seconds)}</div></div><div class="button-row">${button('timer-start',mine&&state.timer.running?'Pause':'Start','',`data-kind="${kind}" data-seconds="${seconds}" data-label="${esc(label)}"`)}${button('timer-reset','Reset','subtle',`data-kind="${kind}" data-seconds="${seconds}" data-label="${esc(label)}"`)}</div></div>`;}
function chartHtml(attempts){const list=attempts.filter(a=>a.listening!==null||a.reading!==null).slice(-6);if(!list.length)return empty('Your baseline goes here','Record a fresh full test to start a useful comparison.','scores','Add a result');return `<div class="legend"><span><i></i>Listening /40</span><span><i class="reading"></i>Academic Reading /40</span></div><div class="chart" role="img" aria-label="Fresh practice results: ${esc(list.map(a=>`${a.source}: listening ${a.listening??'unrecorded'}, reading ${a.reading??'unrecorded'}`).join('; '))}">${list.map(a=>`<div class="chart-group">${a.listening!==null?`<div class="chart-bar" style="height:${a.listening/40*100}%"><span>${a.listening}</span></div>`:''}${a.reading!==null?`<div class="chart-bar reading" style="height:${a.reading/40*100}%"><span>${a.reading}</span></div>`:''}</div>`).join('')}</div><div class="chart-labels">${list.map(a=>`<span>${fmtDate(a.date)}</span>`).join('')}</div>`;}
function drillPage(){return renderDrill({active:activeDrill,drills,state,answers:drillAnswers,result:drillResult,head,button,esc,timerControls,part:practicePart,filter:practiceFilter,freshOnly:practiceFresh,activeLesson:matchingLesson('drill',activeDrill?.id)});}
function scores(){const fresh=freshMocks(state),complete=fresh.filter(a=>a.bands.every(b=>b!==null)),latest=complete.at(-1),value=latest?overall(latest.bands):null,met=latest&&latest.bands.every(b=>b>=9);return head('MEASURE THE RIGHT THINGS','Your mock results.','Log complete tests from official sources. Keep fresh tests, repeats and untimed attempts separate.')+`<div class="grid-even"><section class="card"><div class="card-head"><h2>Record a practice test</h2><span class="tag">FULL TESTS ONLY</span></div><p class="text-small muted">Use the test’s own answer key and band conversion. Raw marks alone do not produce an exact band. Leave unknown scores blank.</p><div class="button-row" style="margin:16px 0">${link(sources[1][1],'Official samples','button outline small')}${link(sources[2][1],'IELTS Ready','button outline small')}</div><form id="mock-form"><div class="form-row"><label for="mock-source">Test source and identifier</label><input id="mock-source" name="source" required maxlength="300" placeholder="e.g. IELTS Ready — Mock 1"></div><div class="field-grid form-row"><div><label for="mock-date">Date completed</label><input id="mock-date" type="date" name="date" value="${dateKey()}" required></div><div><label for="mock-mode">Attempt type</label><select id="mock-mode" name="mode"><option value="fresh">Fresh · first time seeing it</option><option value="repeat">Repeated test</option><option value="untimed">Untimed / paused / with help</option></select></div></div><div class="field-grid form-row"><div><label for="mock-l">Listening /40</label><input id="mock-l" type="number" name="listening" min="0" max="40" step="1" placeholder="Optional"></div><div><label for="mock-r">Academic Reading /40</label><input id="mock-r" type="number" name="reading" min="0" max="40" step="1" placeholder="Optional"></div></div><h3 style="margin-top:22px">Section bands, when available</h3><p class="text-small muted">L/R: enter the source’s reported bands. W/S: use external assessment or a clearly labelled estimate.</p><div class="field-grid four form-row">${['Listening','Reading','Writing','Speaking'].map((s,i)=>`<div><label for="band-${i}">${s}</label><input id="band-${i}" name="band${i}" type="number" min="0" max="9" step="0.5" placeholder="—"></div>`).join('')}</div><div class="form-row"><label for="mock-provenance">Where did the Writing/Speaking bands come from?</label><select id="mock-provenance" name="provenance"><option value="unknown">Not assessed / unknown</option><option value="teacher">Teacher assessment (practice)</option><option value="ai">AI estimate (provisional)</option><option value="self">My own estimate (provisional)</option><option value="official">Official IELTS test result</option></select></div><button class="button">Save test result</button><div id="mock-error" class="form-error" role="alert"></div></form></section><div><section class="card"><div class="card-head"><h2>Latest complete fresh profile</h2><span class="tag">${latest?esc(latest.provenance):'NO PROFILE YET'}</span></div>${latest?`<div class="score-big">${value.toFixed(1)}<small> overall</small></div><div class="profile">${latest.bands.map((b,i)=>`<div><small>${['LISTENING','READING','WRITING','SPEAKING'][i]}</small><strong>${b.toFixed(1)}</strong></div>`).join('')}</div><p class="text-small muted">${esc(latest.source)} · ${fmtDate(latest.date)} · W/S: ${esc(latest.provenance)}.<br>${met?'This recorded profile meets your configured target. Check it again with a fresh test.':'This recorded profile does not yet meet your configured target.'}</p><div class="notice">${latest.provenance==='official'?'A reported official result.':'Practice evidence, not an official result or a guarantee. Self/AI/teacher estimates introduce uncertainty.'} Overall is calculated only from four bands recorded in this same attempt.</div>`:empty('Not enough evidence yet','Record all four section bands in one fresh attempt to see a complete profile. No missing skill is assumed.')}</section><section class="card"><div class="card-head"><h2>Fresh raw-score trend</h2></div>${chartHtml(fresh)}<div class="notice">Published Band 7 benchmark: roughly 30/40 in Listening and Academic Reading. Around 35/40 is the Band 8 benchmark. Exact cutoffs vary. Aim beyond the minimum.</div>${link(sources[0][1],'How IELTS scoring works','text-small')}</section></div></div><section class="card" style="margin-top:22px"><div class="card-head"><h2>Every attempt, honestly labelled</h2><span class="tag">${state.mockAttempts.length} RECORDS</span></div>${state.mockAttempts.length?`<div class="scroll-table"><table><thead><tr><th>Test</th><th>Type</th><th>L /40</th><th>R /40</th><th>Band profile L/R/W/S</th><th></th></tr></thead><tbody>${state.mockAttempts.slice().reverse().map(a=>`<tr><td>${esc(a.source)}<br><small class="muted">${fmtDate(a.date)}</small></td><td><span class="tag ${a.mode==='fresh'?'':'orange'}">${a.mode}</span></td><td title="${esc(rawGuide(a.listening,'Listening'))}">${a.listening??'—'}</td><td title="${esc(rawGuide(a.reading,'Reading'))}">${a.reading??'—'}</td><td>${a.bands.map(b=>b??'—').join(' / ')}<br><small class="muted">W/S: ${esc(a.provenance)}</small></td><td>${button('delete-mock','Delete','subtle small',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your honest starting point','One fresh baseline is more useful than a guessed score.')}</section>`;}
function mistakes(){const sorted=state.mistakes.slice().sort((a,b)=>a.due.localeCompare(b.due));return head('MAKE ERRORS USEFUL','Your mistake notebook.','Recall the answer before revealing it. Review again tomorrow, then space successful recalls further apart.')+`<div class="grid-2"><section><div class="card"><h2>Add something worth remembering</h2><form id="mistake-form"><div class="field-grid form-row"><div><label for="mistake-skill">Skill</label><select id="mistake-skill" name="skill">${['Listening','Reading','Writing','Speaking','Language'].map(x=>`<option>${x}</option>`).join('')}</select></div><div><label for="mistake-tag">Error type</label><input id="mistake-tag" name="tag" maxlength="100" placeholder="e.g. distractor / overview / articles" required></div></div><div class="form-row"><label for="mistake-problem">Question or mistake to recall</label><textarea id="mistake-problem" name="problem" rows="2" maxlength="2000" required></textarea></div><div class="form-row"><label for="mistake-fix">Correction, evidence and rule</label><textarea id="mistake-fix" name="fix" rows="3" maxlength="5000" required></textarea></div><button class="button">Add to tomorrow’s review</button></form></div>${sorted.length?sorted.map(m=>`<article class="mistake-card"><div><span class="tag">${esc(m.skill)}</span><span class="tag">${esc(m.tag)}</span><span class="tag ${m.due<=dateKey()?'orange':''}">${m.due<=dateKey()?'DUE NOW':'REVIEW '+fmtDate(m.due)}</span></div><h3>${esc(m.problem)}</h3>${reviewRevealed.has(m.id)?`<div class="mistake-answer">${esc(m.fix)}</div><p class="text-small muted">Could you explain the correction before seeing it?</p><div class="button-row">${button('review-good','Recalled correctly','',`data-id="${m.id}"`)}${button('review-again','Needs another try','outline',`data-id="${m.id}"`)}${button('delete-mistake','Delete','subtle small',`data-id="${m.id}"`)}</div>`:button('reveal-mistake','Reveal correction','outline small',`data-id="${m.id}"`)}</article>`).join(''):empty('Your errors can teach you','Missed drill questions arrive here automatically. Add errors from official tests and your own writing, too.')}</section><aside><div class="card"><div class="eyebrow">WHY THIS LOOP EXISTS</div><h2 style="margin-top:10px">Retrieve, then check.</h2><p class="text-small muted">Try to explain the answer from memory. Then reveal the correction and compare. Feedback helps prevent a wrong answer from becoming a habit.</p><p class="text-small muted">A successful recall schedules a later review. A miss comes back tomorrow. The intervals are a practical study schedule, not an IELTS score prediction.</p><div class="rule"></div><h3>Measure transfer too</h3><p class="text-small muted">Remembering an old answer is useful. Improving on an unseen official test is stronger evidence that your skill is changing.</p></div></aside></div>`;}
function videosPage(){const list=videos.filter(v=>(videoFilter==='All'||v.skill===videoFilter)&&`${v.title} ${v.topic} ${v.channel}`.toLowerCase().includes(videoSearch.toLowerCase())),practised=videos.filter(v=>state.videos[v.id]?.practised).length;return head('WATCH ONE. DO SOMETHING WITH IT.','Your video library.',`${videos.length} researched YouTube lessons, grouped by skill. Each one has a practice action so the learning continues after the video.`)+`<div class="notice">Start with the crash course and your weakest skill. The longer courses are reference libraries—use relevant chapters, rather than spending the week watching everything. Titles mentioning bands are the creators’ titles, not promises.</div><div class="field-grid"><div class="filter-row" role="group" aria-label="Filter videos by skill">${['All','Orientation','Listening','Reading','Writing','Speaking'].map(f=>`<button class="filter ${f===videoFilter?'active':''}" data-action="video-filter" data-filter="${f}" aria-pressed="${f===videoFilter}">${f}</button>`).join('')}</div><div style="align-self:center"><label class="sr-only" for="video-search">Search videos</label><input id="video-search" type="search" placeholder="Search topics or creators…" value="${esc(videoSearch)}"></div></div><p class="text-small muted">${list.length} lessons shown · ${practised} follow-up exercises marked complete · researched 14 October 2026</p><div class="video-grid">${list.map(v=>{const prog=state.videos[v.id]||{watched:false,practised:false};return `<article class="video-card"><div class="video-top"><span class="skill-label">${esc(v.skill)}<br><small>PREP LESSON</small></span>${link(v.url,'▶','play')}</div><div class="video-body"><div><span class="tag">${esc(v.priority)}</span><span class="tag">${esc(v.topic)}</span></div><h3>${esc(v.title)}</h3><div class="channel">${esc(v.channel)} · YouTube</div><div class="video-exercise"><strong>After watching</strong><br>${esc(v.exercise)}</div><label class="check-item"><input type="checkbox" data-video="${v.id}" data-status="watched" ${prog.watched?'checked':''}><span>I watched the relevant lesson</span></label><label class="check-item"><input type="checkbox" data-video="${v.id}" data-status="practised" ${prog.practised?'checked':''}><span>I completed the follow-up exercise</span></label>${link(v.url,'Watch on YouTube','button outline small')}</div></article>`;}).join('')}</div>${!list.length?empty('No matching lessons','Try a different topic or clear the search.'):''}`;}
function settings(){return head('YOUR PLAN. YOUR DATA.','Make it work for you.','Set your dates, keep a backup, and see the sources behind the study tools.')+`<div class="grid-even"><div><section class="card"><h2>Your study settings</h2><form id="settings-form"><div class="field-grid form-row"><div><label for="settings-start">Preparation starts</label><input id="settings-start" name="start" type="date" value="${state.settings.start}" required></div><div><label for="settings-exam">Test date</label><input id="settings-exam" name="exam" type="date" value="${state.settings.exam}" required></div></div><div class="field-grid form-row"><div><label for="settings-hours">Focused study hours/day</label><input id="settings-hours" name="hours" type="number" value="${state.settings.hours}" min="1" max="8" step="0.5" required></div><div><label for="settings-min">Minimum in each section, if required</label><select id="settings-min" name="minimum"><option value="">No section minimum entered</option>${[5,5.5,6,6.5,7,7.5,8,8.5,9].map(x=>`<option value="${x}" ${state.settings.minimum===x?'selected':''}>${x.toFixed(1)}</option>`).join('')}</select></div></div><button class="button">Save settings</button><div id="settings-error" class="form-error" role="alert"></div></form><p class="text-small muted">Target: Band 9 in Listening, Reading, Writing and Speaking. Keep your university’s actual requirement separate from this training goal. Keep a normal sleep schedule; more exhausted hours do not make better evidence.</p></section><section class="card"><h2>Your work stays with you</h2><p class="text-small muted">Drafts, notes, scores and progress are saved in this browser on this device. They do not automatically sync between devices. Clearing browser data can erase them.</p><p class="text-small muted">Export a backup regularly. Speaking audio stays in the current session only—download recordings separately.</p><div class="button-row">${button('export-data','Export backup')}${button('choose-import','Import backup','outline')}${button('download-summary','Download progress report','subtle')}</div><div class="button-row" style="margin-top:10px">${button('backup-text','Copy/paste backup','outline small')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="rule"></div>${button('reset-data','Reset all saved work','outline small')}<div class="notice ${storageAvailable?'':'warning'}">${storageAvailable?'Browser storage is available. A backup gives you a portable copy.':'Storage is currently unavailable or a saved record could not be loaded. Export this session before leaving. Existing stored data has not been intentionally deleted.'}</div></section></div><section class="card"><div class="eyebrow">RESEARCH & LIMITS</div><h2 style="margin-top:10px">What the app measures</h2><p class="research-note">Full-test raw scores come from the answer keys you use. Overall band arithmetic uses only four section bands from a single recorded attempt. Writing checklists, word counts and timer use do not establish a band.</p><p class="research-note">The original mini drills measure item accuracy. Repeats are labelled. The mistake notebook uses recall, corrective feedback and spaced revisits. These are research-informed study tools; this particular app has not been validated as an IELTS intervention.</p><p class="research-note">Optional AI coaching runs on this device. It needs no account or API key, and your answers are not uploaded. Enabling it downloads model files to your browser cache. A compatible browser and sufficient memory are needed; quick language checks and lessons work without it.</p><p class="research-note">The on-device coach gives uncalibrated feedback without IELTS band scores. Keep independently assessed full mock results for measuring bands. Local speech recognition creates a draft transcript you must check; text cannot establish pronunciation or spoken fluency. Legacy AI reports remain labelled with their original provider.</p><p class="research-note">${link('https://webllm.mlc.ai/','On-device AI runtime')} · ${link('https://huggingface.co/docs/transformers.js','Local speech recognition')}</p><div class="rule"></div><div class="sources-list">${sources.map(s=>`${link(s[1],s[0])}<p>${esc(s[2])}</p>`).join('')}</div><p class="text-small muted">Sources and video links researched 14 October 2026. Free resources can have optional paid products; sign-up may be required.</p></section></div>`;}
const mainNav=[['today','01','Your next session'],['learn','02','Learn & practise'],['drills','03','Practice tests'],['progress','04','Your progress'],['more','05','All tools']];
function render(){ensureLearning(state);const raw=location.hash.slice(1)||'today';route=raw.startsWith('lesson-')?'lesson':raw;if(route==='lesson'&&lessons.some(l=>l.id===raw.slice(7)))ensureLearning(state).current=raw.slice(7);if(![...nav.map(n=>n[0]),'learn','progress','more','lesson','grading','band9'].includes(route))route='today';const group=['today','learn','drills','progress','more'].includes(route)?route:route==='lesson'||['writing','speaking','drills'].includes(route)?'learn':route==='scores'?'progress':'more';$('#navigation').innerHTML=mainNav.map(n=>`<a href="#${n[0]}" class="nav-item ${n[0]===group?'active':''}" ${n[0]===group?'aria-current="page"':''}><span class="nav-num">${n[1]}</span>${n[2]}</a>`).join('');try{let view=route==='lesson'?learningUI.lesson(raw.slice(7)):({today:learningUI.today,learn:learningUI.learn,progress:learningUI.progress,more:learningUI.more,grading:studio.hub,band9:studio.band9,writing,speaking,drills:drillPage,scores,mistakes,videos:videosPage,settings}[route])();if(route==='today')view=studio.quickStart()+view;if(route==='progress')view+=studio.recent();const banner=(route==='writing'&&matchingLesson('writing',prompt().id))||(route==='speaking'&&matchingLesson('speaking',String(state.selectedCue)))||(route==='drills'&&matchingLesson('drill',activeDrill?.id));$('#main').innerHTML=(banner?learningUI.banner():'')+view;storageWarning();}catch(e){$('#main').innerHTML=empty('This view could not load','Your saved work is still in this browser. Try reloading or open Settings.','settings','Open Settings');console.error(e);}const title=({grading:'AI feedback',band9:'Your Band 9 plan'}[route])||mainNav.find(n=>n[0]===route)?.[2]||nav.find(n=>n[0]===route)?.[2]||'Guided session';document.title=`${title} · Band Nine`;updateTimer();if(!storageAvailable)$('#save-status').textContent='Storage issue — export a backup';}
function matchingLesson(type,id){const l=lessons.find(l=>l.id===ensureLearning(state).practice);return l?.practice.type===type&&String(l.practice.id)===String(id)?l:null;}
function reviewChecks(p){return getWritingMinimum(p)===60?['My paragraph has one clear main claim.','I explained why or how that claim holds.','I added a relevant example or consequence.','Each sentence develops the same idea.','My vocabulary is precise and appropriate.','I checked grammar and punctuation.']:checks[p.type];}
function getWritingMinimum(p){return matchingLesson('writing',p.id)?.id==='writing-paragraph-development'?60:p.type===1?150:250;}
function writing(){let html=studio.writing();if(writingReport?.promptId===prompt().id&&writingReport.text===draft().text){const r=writingReport.report;html+=`<section class="card revision-report" id="writing-report"><span class="eyebrow">OFFLINE LANGUAGE CHECKS · NOT AN AI GRADE</span><h2>Quick patterns to inspect</h2>${r.findings.map(f=>`<div class="revision-item"><h3>${esc(f.title)}</h3>${f.quote?`<blockquote>${esc(f.quote)}</blockquote>`:''}<p>${esc(f.detail)}</p></div>`).join('')}<ol>${r.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol></section>`;}return html;}
function speaking(){return studio.speaking();}
